package com.vandorlabs.navigation;
/** Exact range endpoints, continuous arm height and capped linear size bonus. */
public final class NavigationRangeTest {
 public static void main(String[] args){int cases=0;for(int base:new int[]{1000,5000}){need(NavigationRange.radius(base,64)==base/2&&NavigationRange.radius(base,128)==base,"released altitude endpoints");need(NavigationRange.radius(base,-1000)==base/8&&NavigationRange.radius(base,16)==base/8,"low height minimum");for(double size:new double[]{1,1.25,1.5,2,3,8}){need(NavigationRange.radius(base,64,size)==base/2,"size does not alter Y64");int cap=(int)Math.round(base*(1+Math.min(1,size-1)));need(NavigationRange.radius(base,128,size)==cap&&NavigationRange.radius(base,10000,size)==cap,"size and altitude caps");int previous=0;for(int y=-32;y<=192;y++){int radius=NavigationRange.radius(base,y,size);need(radius>=previous&&radius<=base*2,"monotone bounded height response");previous=radius;cases++;}need(NavigationRange.radius(base,96,size)==(int)Math.round(base*(.75+Math.min(1,size-1)*.5)),"half size bonus at Y96");}need(NavigationRange.radius(base,65)>NavigationRange.radius(base,64)&&NavigationRange.radius(base,64.25,2)>NavigationRange.radius(base,64,2),"fractional physical arm height applied without percent steps");}need(NavigationRange.radius(5000,128,4/3.0)==6667&&NavigationRange.radius(5000,128,5/3.0)==8333&&NavigationRange.radius(5000,128,2)==10000,"Dish4/5/6cube endpoints");need(NavigationRange.radius(1000,128,1.5)==1500&&NavigationRange.radius(1000,128,2)==2000,"Array3x6/4x8 endpoints");for(double bad:new double[]{Double.NaN,Double.POSITIVE_INFINITY,Double.NEGATIVE_INFINITY})need(NavigationRange.radius(5000,bad,1)==0&&NavigationRange.radius(5000,128,bad)==0,"nonfinite refused");need(NavigationRange.radius(0,128,1)==0&&NavigationRange.radius(1000,128,.99)==0,"invalid maximum or size refused");System.out.println("NavigationRangeTest PASS heightCases="+cases+" baseEndpoints/fractionalArms/linearBonus/cappedAtDouble/invalidInput");}
 private static void need(boolean value,String message){if(!value)throw new AssertionError(message);}
}
